package com.andye.warmod.artillery.network;
import com.andye.warmod.WarMod;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record ServerboundArtilleryFirePayload(int menuId, BlockPos position) implements CustomPacketPayload { public static final Type<ServerboundArtilleryFirePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"artillery_fire")); public static final StreamCodec<RegistryFriendlyByteBuf,ServerboundArtilleryFirePayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.menuId);b.writeBlockPos(p.position);},b->new ServerboundArtilleryFirePayload(b.readVarInt(),b.readBlockPos()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;} }
